import { boundsOf, encodeGeometry } from './geometry.js';

// GeoPackage writer: features, their R-tree index and the layer extent.
export function writeFeatures(db, table, features) {
  const insert = db.prepare('INSERT INTO "' + table + '" (fid, geom) VALUES (?, ?)');
  const index = db.prepare('INSERT INTO "rtree_' + table + '_geom" VALUES (?, ?, ?, ?, ?)');
  const extent = [Infinity, Infinity, -Infinity, -Infinity];
  for (const feature of features) {
    const [minX, minY, maxX, maxY] = boundsOf(feature.geometry);
    insert.run(feature.id, encodeGeometry(feature.geometry));
    index.run(feature.id, minX, maxX, minY, maxY);
    extent[0] = Math.min(extent[0], minX);
    extent[1] = Math.min(extent[1], minY);
    extent[2] = Math.max(extent[2], maxX);
    extent[3] = Math.max(extent[3], maxY);
  }
  return extent;
}
